require "test_helper"

class CollisionTest < ActiveSupport::TestCase
  setup do
    @book = books(:manual)
    # Create leaves in order: first, second, third
    @first = @book.press(Page.new(body: "1"), title: "First")
    @second = @book.press(Page.new(body: "2"), title: "Second")
    @third = @book.press(Page.new(body: "3"), title: "Third")
    # They have scores 1, 2, 3 by default (inserted at end)
    # Now rearrange: second(1), third(2), first(3) 
    @second.update!(position_score: 1)
    @third.update!(position_score: 2)
    @first.update!(position_score: 3)
  end

  test "restored leaf comes back in correct position after compaction" do
    # Trash @second (which is at position 1 after rearrangement)
    @second.trashed!

    # Active: @third(2), @first(3) — gap at 1
    @book.compact_positions!

    # Restore @second
    @second.update!(status: :active)

    # @second should come back at position 1 (its original place before trashing)
    # It should be before @third and @first
    order = @book.leaves.active.positioned.to_a
    assert_equal [@second, @third, @first], order,
      "restored leaf should be in its original relative position"
  end
end
