require "test_helper"

class CollisionTest2 < ActiveSupport::TestCase
  setup do
    @book = books(:manual)
    # Create leaves in order: first, second, third (ids: first < second < third)
    @first = @book.press(Page.new(body: "1"), title: "First")
    @second = @book.press(Page.new(body: "2"), title: "Second")
    @third = @book.press(Page.new(body: "3"), title: "Third")
    # Rearrange so third (highest id) is first: third(1), first(2), second(3)
    @third.update!(position_score: 1)
    @first.update!(position_score: 2)
    @second.update!(position_score: 3)
  end

  test "restored leaf comes back in correct position after compaction" do
    # Verify rearrangement
    assert_equal [@third, @first, @second], @book.leaves.active.positioned.to_a

    # Trash @third (position 1, but highest id)
    @third.trashed!

    # Active: @first(2), @second(3) — gap at 1
    @book.compact_positions!

    # Restore @third
    @third.update!(status: :active)

    # @third should come back at position 1 (before @first and @second)
    order = @book.leaves.active.positioned.to_a
    assert_equal [@third, @first, @second], order,
      "restored leaf should be in its original relative position, not determined by id"
  end
end
